PRAGMA foreign_keys=ON;
CREATE TABLE users(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT NOT NULL UNIQUE COLLATE NOCASE,password_hash TEXT NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('author','reviewer','chair','admin')),affiliation TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE password_reset_tokens(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TEXT NOT NULL,used_at TEXT);
CREATE TABLE conferences(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,active_phase TEXT CHECK(active_phase IN('submission','review','rebuttal','decision')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE conference_chairs(conference_id INTEGER NOT NULL REFERENCES conferences(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id),PRIMARY KEY(conference_id,user_id));
CREATE TABLE conference_phases(id INTEGER PRIMARY KEY AUTOINCREMENT,conference_id INTEGER NOT NULL REFERENCES conferences(id) ON DELETE CASCADE,phase TEXT NOT NULL CHECK(phase IN('submission','review','rebuttal','decision')),starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'inactive' CHECK(status IN('inactive','active','completed')),UNIQUE(conference_id,phase));
CREATE TABLE submissions(id INTEGER PRIMARY KEY AUTOINCREMENT,conference_id INTEGER NOT NULL REFERENCES conferences(id),title TEXT NOT NULL,abstract TEXT NOT NULL,keywords_json TEXT NOT NULL,track TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN('draft','submitted','under_review','withdrawn','decided')),version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE submission_authors(submission_id INTEGER NOT NULL REFERENCES submissions(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id),author_order INTEGER NOT NULL,is_corresponding INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(submission_id,user_id));
CREATE TABLE stored_files(id INTEGER PRIMARY KEY AUTOINCREMENT,original_name TEXT NOT NULL,stored_name TEXT NOT NULL UNIQUE,mime_type TEXT NOT NULL,size_bytes INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE manuscripts(id INTEGER PRIMARY KEY AUTOINCREMENT,submission_id INTEGER NOT NULL REFERENCES submissions(id) ON DELETE CASCADE,file_id INTEGER NOT NULL REFERENCES stored_files(id),version INTEGER NOT NULL,is_current INTEGER NOT NULL DEFAULT 1,uploaded_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(submission_id,version));
CREATE TABLE conflicts(id INTEGER PRIMARY KEY AUTOINCREMENT,submission_id INTEGER NOT NULL REFERENCES submissions(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id),reason TEXT NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(submission_id,user_id));
CREATE TABLE review_assignments(id INTEGER PRIMARY KEY AUTOINCREMENT,submission_id INTEGER NOT NULL REFERENCES submissions(id) ON DELETE CASCADE,reviewer_id INTEGER NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'assigned' CHECK(status IN('assigned','in_progress','submitted','reopened')),assigned_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(submission_id,reviewer_id));
CREATE TABLE reviews(id INTEGER PRIMARY KEY AUTOINCREMENT,assignment_id INTEGER NOT NULL UNIQUE REFERENCES review_assignments(id) ON DELETE CASCADE,scores_json TEXT NOT NULL DEFAULT '{}',confidence INTEGER,summary TEXT NOT NULL DEFAULT '',comments_to_authors TEXT NOT NULL DEFAULT '',confidential_comments TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','submitted')),updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,submitted_at TEXT);
CREATE TABLE rebuttals(id INTEGER PRIMARY KEY AUTOINCREMENT,submission_id INTEGER NOT NULL UNIQUE REFERENCES submissions(id) ON DELETE CASCADE,rebuttal_text TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','submitted')),updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,submitted_at TEXT);
CREATE TABLE decisions(id INTEGER PRIMARY KEY AUTOINCREMENT,submission_id INTEGER NOT NULL UNIQUE REFERENCES submissions(id) ON DELETE CASCADE,decision TEXT NOT NULL CHECK(decision IN('accept','reject','conditional_accept')),rationale TEXT NOT NULL,conditions TEXT NOT NULL DEFAULT '',released_at TEXT,decided_by INTEGER NOT NULL REFERENCES users(id),updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notifications(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,type TEXT NOT NULL,message TEXT NOT NULL,link TEXT NOT NULL DEFAULT '',read_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE submission_activity(id INTEGER PRIMARY KEY AUTOINCREMENT,submission_id INTEGER NOT NULL REFERENCES submissions(id) ON DELETE CASCADE,actor_id INTEGER REFERENCES users(id),event TEXT NOT NULL,details TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_events(id INTEGER PRIMARY KEY AUTOINCREMENT,actor_id INTEGER REFERENCES users(id),action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_sessions_expiry ON sessions(expires_at);CREATE INDEX idx_submission_conf_status ON submissions(conference_id,status);CREATE INDEX idx_assignment_reviewer ON review_assignments(reviewer_id,status);CREATE INDEX idx_notification_recipient ON notifications(user_id,read_at);
